// HasRealm applies the HasEdge predicate on the "realm" edge.
func HasRealm() predicate.UserImportJob {
	return predicate.UserImportJob(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, RealmTable, RealmColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRealmWith applies the HasEdge predicate on the "realm" edge with a given conditions (other predicates).
func HasRealmWith(preds ...predicate.Realm) predicate.UserImportJob {
	return predicate.UserImportJob(func(s *sql.Selector) {
		step := newRealmStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.UserImportJob) predicate.UserImportJob {
	return predicate.UserImportJob(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UserImportJob) predicate.UserImportJob {
	return predicate.UserImportJob(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UserImportJob) predicate.UserImportJob {
	return predicate.UserImportJob(sql.NotPredicates(p))
}
